import { Accessor, createContext, createMemo, Owner, runWithOwner, Show, useContext } from "solid-js";

import { defineLegacyComponent } from "#core/ui-next/components/fxs-solid-component.js";
import { TooltipKeyword } from "#core/ui-next/components/tooltip-keyword.js";
import {
	Tooltip,
	TooltipContext,
	TooltipHorizontalPosition,
	TooltipVerticalPosition,
} from "#core/ui-next/components/tooltip.jsx";
import { isFocusable } from "#core/ui-next/services/focus.js";
const _PROTECTED_IMPORTS = [isFocusable];

export interface NestedTooltipContextData {
	/**
	 * When true (or returns true) tooltips defined inside this context will be
	 * suppressed. Supports an Accessor so the disabled state can be reactive.
	 */
	disabled?: boolean | Accessor<boolean>;
}
export const NestedTooltipContext = createContext<NestedTooltipContextData>();

/**
 * Read the disabled flag from a {@link NestedTooltipContextData}, supporting
 * both static booleans and reactive accessors. Call from a reactive scope to
 * track changes when an accessor is used.
 */
export const isNestedTooltipContextDisabled = (ctx: NestedTooltipContextData | undefined): boolean => {
	const disabled = ctx?.disabled;
	if (!disabled) {
		return false;
	}
	return typeof disabled === "function" ? disabled() : disabled;
};

/**
 * Find the owner of a Solid.js component from a DOM element
 *
 * @param element element to start the search at
 */
const findOwnerFromElement = (element: HTMLElement | null): Owner | null => {
	if (!element) return null;

	let current: HTMLElement | null = element;
	while (current) {
		const owner = current.owner;
		if (owner) return owner;

		current = current.parentElement;
	}

	return null;
};

defineLegacyComponent(
	"fxs-tip",
	{ attrs: { "data-content": null, "data-caption": null }, initializeImmediately: true },
	(attrs, element) => {
		if (!element || !(element instanceof HTMLElement)) {
			throw new Error("fxs-tip requires a host element");
		}

		const owner = findOwnerFromElement(element.parentElement);
		const keywordText = element.textContent?.trim();

		const tooltipCaption = createMemo(() => {
			if (attrs["data-caption"]) {
				return attrs["data-caption"].trim();
			}
			return "";
		});

		return owner == null ? (
			<span
				class="text-accent-1"
				innerHTML={tooltipCaption()} // eslint-disable-line solid/no-innerhtml
			/>
		) : (
			runWithOwner(owner, () => {
				const ctx = useContext(TooltipContext);
				const nestedCtx = useContext(NestedTooltipContext);

				const tooltipText = createMemo(() => {
					if (attrs["data-content"]) {
						return attrs["data-content"].trim();
					}
					return "";
				});

				// we want nested tooltips to be positioned at the bottom right by default, but we want to ensure
				// they cascade properly from any parent tooltip settings
				const initialVPosition =
					ctx?.vPosition() === TooltipVerticalPosition.TOP
						? TooltipVerticalPosition.TOP
						: TooltipVerticalPosition.BOTTOM;
				const initialHPosition =
					ctx?.hPosition() === TooltipHorizontalPosition.LEFT
						? TooltipHorizontalPosition.LEFT
						: TooltipHorizontalPosition.RIGHT;
				let activatableRef!: HTMLDivElement;

				return (
					<Show
						when={!isNestedTooltipContextDisabled(nestedCtx)}
						fallback={
							<span
								class="text-accent-1"
								innerHTML={tooltipCaption()} // eslint-disable-line solid/no-innerhtml
							/>
						}
					>
						<Tooltip.Text
							header={keywordText}
							text={tooltipText()}
							initialVPosition={initialVPosition}
							initialHPosition={initialHPosition}
							allowFlip={true}
						>
							<TooltipKeyword ref={activatableRef}>{tooltipCaption()}</TooltipKeyword>
						</Tooltip.Text>
					</Show>
				);
			})
		);
	},
);
